use super::*;

/// Whether a phy's mode list includes monitor mode.
pub fn monitor_from_modes(modes: &[String]) -> Tristate {
    if modes.is_empty() {
        return Tristate::Unknown;
    }
    if modes.iter().any(|m| m == "monitor") {
        Tristate::Yes
    } else {
        Tristate::No
    }
}
